mapper.update:
UPDATE herb_batch
SET remark = #{remark},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND is_deleted = 0

UPDATE herb_batch
SET collect_end_time = #{collectEndTime},
    remark = #{remark},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND is_deleted = 0

mapper.select:
SELECT
FROM herb_batch b LEFT JOIN herb_collection_task t ON t.id = b.task_id AND t.is_deleted = 0
ORDER BY b.created_at DESC LIMIT #{offset}, #{pageSize}
